'use client';

import { useState } from 'react';
import { Search, HelpCircle } from 'lucide-react';
import Link from 'next/link';
import { PageHeader } from '@/components/shared/page-header';
import { CTABlock } from '@/components/shared/cta-block';
import { Accordion } from '@/components/ui/accordion';

interface FaqItem {
  question: string;
  answer: string;
  category: string;
}

const tabs = [
  { id: 'all', label: 'All' },
  { id: 'general', label: 'General' },
  { id: 'account', label: 'Account' },
  { id: 'selling', label: 'Selling' },
  { id: 'buying', label: 'Buying' },
  { id: 'payments', label: 'Payments' },
  { id: 'shipping', label: 'Shipping' },
  { id: 'returns', label: 'Returns' },
];

const faqItems: FaqItem[] = [
  { category: 'general', question: 'What is TRADINGO?', answer: 'TRADINGO is India\'s first Trusted Electronic Marketplace (TEM), a B2B platform connecting verified buyers and sellers across industries. We combine an AI-powered commerce engine (TRADHEXA) with secure escrow payments, quality assurance, and end-to-end trade management.' },
  { category: 'general', question: 'Is TRADINGO free to use?', answer: 'Creating an account and browsing the marketplace is free. Sellers are charged commission on successful transactions, and optional subscription plans (Trade Smart, Plus, Pro, Premium, Elite) offer additional features and reduced commission rates.' },
  { category: 'general', question: 'Which industries does TRADINGO serve?', answer: 'TRADINGO serves a wide range of B2B industries including industrial goods, chemicals, electronics, food processing, packaging, textiles, construction materials, and more. Our catalog spans hundreds of categories.' },
  { category: 'general', question: 'What is the TEM framework?', answer: 'TEM stands for Trusted Electronic Marketplace, TRADINGO\'s proprietary framework that combines verified profiles, escrow payments, quality assurance, TradTrust scoring, and AI-powered matchmaking to create a trusted B2B trading environment.' },
  { category: 'general', question: 'How does TRADINGO ensure trust?', answer: 'Trust is ensured through multi-level verification (KYC, business documents), TradTrust reputation scoring, secure escrow payments, buyer protection policies, AI-powered fraud detection, and a structured dispute resolution process.' },
  { category: 'account', question: 'How do I create an account?', answer: 'Click "Register" on the homepage, choose Buyer or Seller account type, fill in your details, complete email verification, and submit the required documents for verification. Your account will be activated once verification is complete.' },
  { category: 'account', question: 'What documents are needed for verification?', answer: 'For buyers: government-issued ID and address proof. For sellers: GST registration, PAN card, business registration certificate, address proof, and bank account details. Additional documents may be required for specific categories.' },
  { category: 'account', question: 'How long does verification take?', answer: 'Basic email and mobile verification is instant. Business document verification typically takes 24-48 hours. Complex verifications may take up to 5 business days.' },
  { category: 'account', question: 'Can I have both a buyer and seller account?', answer: 'Yes, you can use the same account to both buy and sell. However, you must complete verification requirements for both roles separately.' },
  { category: 'account', question: 'How do I reset my password?', answer: 'Click "Forgot Password" on the login page, enter your registered email, and follow the password reset link sent to your inbox. The link expires in 1 hour for security.' },
  { category: 'account', question: 'How do I delete my account?', answer: 'Go to Account Settings > Security > Delete Account. Note that pending orders must be resolved before deletion, and some data may be retained as required by law.' },
  { category: 'selling', question: 'How do I list a product?', answer: 'Navigate to your Seller Dashboard > Products > Add Product. Fill in product details including title, description, category, price, stock, specifications, and upload high-quality images. Submit for review after completing all required fields.' },
  { category: 'selling', question: 'What are the seller commission rates?', answer: 'Commission rates vary by product category and your subscription plan. Rates range from 2-15% of the transaction value. Detailed rates are available on our pricing page and in your seller dashboard.' },
  { category: 'selling', question: 'How do I manage orders?', answer: 'Orders appear in your Seller Dashboard under Orders. You can view order details, update status (processing, shipped, delivered), communicate with buyers, and generate invoices from the order management panel.' },
  { category: 'selling', question: 'What happens if I cannot fulfill an order?', answer: 'Contact the buyer immediately through the platform and cancel the order. Multiple cancellations may affect your seller rating and TradTrust score. TRADINGO may charge cancellation fees for excessive cancellations.' },
  { category: 'selling', question: 'How do I get paid?', answer: 'Settlement amounts are disbursed to your registered bank account on a T+3 basis after delivery confirmation. You can track your earnings and payment history under Seller Dashboard > Finance.' },
  { category: 'selling', question: 'Can I offer discounts or promotions?', answer: 'Yes, you can create promotional campaigns, offer volume discounts, and set special pricing for bulk orders. Use the Campaigns section in your seller dashboard to set up promotions.' },
  { category: 'buying', question: 'How do I find products?', answer: 'Use the search bar, browse by category, or use TradFind AI-powered search. You can filter results by price, supplier location, rating, verification level, and other criteria.' },
  { category: 'buying', question: 'What is an RFQ?', answer: 'RFQ stands for Request for Quote. You can submit an RFQ specifying your product requirements, quantity, and budget. Multiple suppliers can respond with quotes, and you can compare and choose the best offer.' },
  { category: 'buying', question: 'How do I compare supplier quotes?', answer: 'Use the Quote Comparison tool to view side-by-side comparisons of price, delivery time, payment terms, seller ratings, and TradTrust scores. Our AI highlights the best-value option based on your preferences.' },
  { category: 'buying', question: 'Can I negotiate with sellers?', answer: 'Yes, TRADINGO offers a Smart Negotiation feature that facilitates structured price and term negotiations between buyers and sellers. Our AI can assist with negotiation strategy and counteroffers.' },
  { category: 'buying', question: 'How do I save products for later?', answer: 'Click the bookmark icon on any product card or product page to save it to your Saved Products list. Access your saved items from your buyer dashboard.' },
  { category: 'payments', question: 'What payment methods are accepted?', answer: 'We accept bank transfers (NEFT/RTGS/IMPS), credit/debit cards, UPI, and net banking. Available methods may vary based on transaction value and your verification level.' },
  { category: 'payments', question: 'How does escrow payment work?', answer: 'When you place an order, your payment is held in TRADINGO\'s secure escrow account. The funds are released to the seller only after you confirm satisfactory delivery. This protects both parties.' },
  { category: 'payments', question: 'When will my payment be released to the seller?', answer: 'Payment is released to the seller after you confirm delivery or after the auto-confirmation period expires (typically 7 days after delivery). Disputed orders may extend the holding period.' },
  { category: 'payments', question: 'What is GOCASH?', answer: 'GOCASH is TRADINGO\'s rewards currency earned through platform activities, referrals, campaigns, and ecosystem participation. GOCASH can be redeemed for platform services, advertising credits, and other benefits.' },
  { category: 'payments', question: 'Are there any transaction fees?', answer: 'Buyers do not pay additional transaction fees. The price you see includes all applicable charges. Sellers pay commission as per their plan. Payment gateway charges are covered by TRADINGO.' },
  { category: 'shipping', question: 'How are shipping costs calculated?', answer: 'Shipping costs depend on product weight, dimensions, destination, and delivery speed. Costs are displayed during checkout before payment. Some sellers may offer free shipping on qualifying orders.' },
  { category: 'shipping', question: 'How do I track my order?', answer: 'Tracking information is available in your order details under Orders > Active Orders. You will receive email and in-app notifications when your order status changes.' },
  { category: 'shipping', question: 'What if my order is delayed?', answer: 'If your order exceeds the estimated delivery date, contact the seller through the platform. If the seller does not resolve the issue within 48 hours, you can escalate to TRADINGO support for assistance.' },
  { category: 'shipping', question: 'Can I change my delivery address?', answer: 'You can change the delivery address before the order is dispatched. Once shipped, address changes may not be possible. Contact the seller immediately if you need to update the address.' },
  { category: 'returns', question: 'What is the return policy?', answer: 'Most products can be returned within 7-14 days of delivery if defective, damaged, or not as described. Return eligibility varies by product category and seller policy. Custom and perishable items may be non-returnable.' },
  { category: 'returns', question: 'How do I initiate a return?', answer: 'Go to Orders > select the order > Request Return. Provide the reason and upload supporting evidence (photos/videos). The seller will review your request and respond within 48 hours.' },
  { category: 'returns', question: 'How long do refunds take?', answer: 'Once the seller approves the return and receives the product back, refunds are processed within 5-10 business days. Refunds are credited to your original payment method or GOCASH wallet.' },
  { category: 'returns', question: 'Who pays for return shipping?', answer: 'If the return is due to seller error (defective, wrong item, damaged), the seller bears the return shipping cost. For buyer-initiated returns, the buyer may be responsible for return shipping charges.' },
  { category: 'returns', question: 'What if the seller rejects my return request?', answer: 'If you believe the rejection is unfair, you can escalate to TRADINGO\'s dispute resolution team within 7 days. Our team will review evidence from both parties and make a binding decision.' },
];

const relatedArticles = [
  { title: 'Understanding TradTrust Scores', href: '/help/faq' },
  { title: 'GOCASH Rewards Program Guide', href: '/help/faq' },
  { title: 'Bulk Ordering and RFQ Best Practices', href: '/help/faq' },
  { title: 'Security Best Practices for Your Account', href: '/help/faq' },
  { title: 'GST Invoicing and Compliance Guide', href: '/help/faq' },
];

export default function FaqPage() {
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  const filteredItems = faqItems.filter((item) => {
    const matchesTab = activeTab === 'all' || item.category === activeTab;
    const matchesSearch = searchQuery.length === 0
      || item.question.toLowerCase().includes(searchQuery.toLowerCase())
      || item.answer.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesTab && matchesSearch;
  });

  const groupedItems = filteredItems.reduce<Record<string, FaqItem[]>>((acc, item) => {
    if (!acc[item.category]) acc[item.category] = [];
    acc[item.category].push(item);
    return acc;
  }, {});

  const categoryLabels: Record<string, string> = {
    general: 'General',
    account: 'Account',
    selling: 'Selling',
    buying: 'Buying',
    payments: 'Payments',
    shipping: 'Shipping',
    returns: 'Returns',
  };

  return (
    <>
      <PageHeader
        title="Frequently Asked Questions"
        description="Find quick answers to common questions about TRADINGO."
      />

      <section className="py-8">
        <div className="container-main">
          <div className="mx-auto max-w-2xl">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-text-tertiary" />
              <input
                type="text"
                placeholder="Search FAQs..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full rounded-xl border border-border bg-surface py-3 pl-12 pr-4 text-text-primary placeholder:text-text-tertiary focus:border-accent focus:outline-none focus:ring-1 focus:ring-accent"
              />
            </div>
          </div>
        </div>
      </section>

      <section className="py-4">
        <div className="container-main">
          <div className="mx-auto max-w-3xl">
            <div className="mb-8 flex flex-wrap gap-2">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setActiveTab(tab.id)}
                  className={`rounded-lg px-4 py-2 text-sm font-medium transition-all ${
                    activeTab === tab.id
                      ? 'bg-accent text-white'
                      : 'bg-surface text-text-secondary hover:bg-surface-secondary hover:text-text-primary'
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {filteredItems.length === 0 ? (
              <div className="rounded-xl border border-border bg-surface p-12 text-center">
                <HelpCircle className="mx-auto mb-4 h-12 w-12 text-text-tertiary" />
                <h3 className="mb-2 text-lg font-semibold text-text-primary">No FAQs found</h3>
                <p className="text-text-secondary">Try adjusting your search or filter to find what you are looking for.</p>
              </div>
            ) : (
              <div className="space-y-8">
                {Object.entries(groupedItems).map(([category, items]) => (
                  <div key={category}>
                    <h2 className="mb-4 text-xl font-bold text-text-primary">
                      {categoryLabels[category] || category}
                    </h2>
                    <Accordion
                      items={items.map((item) => ({
                        value: item.question,
                        title: item.question,
                        children: <p>{item.answer}</p>,
                      }))}
                      type="multiple"
                    />
                  </div>
                ))}
              </div>
            )}

            <div className="mt-12 rounded-xl border border-border bg-surface p-6">
              <h2 className="mb-4 text-xl font-bold text-text-primary">Related Articles</h2>
              <div className="space-y-3">
                {relatedArticles.map((article) => (
                  <Link
                    key={article.title}
                    href={article.href}
                    className="group flex items-center gap-2 rounded-lg p-2 transition-all hover:bg-surface-secondary"
                  >
                    <span className="text-sm text-text-secondary group-hover:text-accent">{article.title}</span>
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      <CTABlock
        title="Still Have Questions?"
        subtitle="Our support team is here to help you with any unanswered questions."
        primaryLabel="Contact Support"
        primaryHref="/contact"
        variant="simple"
      />
    </>
  );
}
